def cmd_group(args, opts):
    _need_at_least(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        dup = next(a for i, a in enumerate(args[2:]) if a in args[2:i + 2])
        raise UsageError("group: aggregate %r given twice" % dup)
    aggregates = [_parse_aggregate(a) for a in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    wanted = [(name, None if column is None else (table.index(column), column)) for name, column in aggregates]
    names = [args[1]] + [a.replace(":", "_") for a in args[2:]]
    for name in names:
        if names.count(name) > 1:
            raise TabulaError("result would have column %r twice" % name)
    groups = {}
    for n, row in enumerate(table.rows, 1):
        members = groups.setdefault(row[by], [])
        members.append([None if w is None else _cell_number(table, n, w[1], row[w[0]]) for _, w in wanted])
    # sums of long numbers must stay exact: size the precision to the longest cell
    digits = max([len(c) for row in table.rows for c in row] + [28]) + len(str(len(table.rows))) + 30
    rows = []
    with localcontext() as ctx:
        ctx.prec = digits
        for key, members in groups.items():
            out = [key]
            for i, (name, _) in enumerate(wanted):
                values = [m[i] for m in members]
                if name == "count":
                    out.append(str(len(members)))
                elif name == "sum":
                    out.append(fmt_decimal(sum(values, Decimal(0))))
                elif name == "min":
                    out.append(fmt_decimal(min(values)))
                elif name == "max":
                    out.append(fmt_decimal(max(values)))
                else:
                    out.append(fmt_2dp(sum(values, Decimal(0)) / len(values)))
            rows.append(out)
    return Table(names, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left = load(args[0])
    left_at = left.index(args[2])
    right = load(args[1])
    right_at = right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != right_at]
    names = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                            for i in kept]
    for name in names:
        if names.count(name) > 1:
            raise TabulaError("join: result would have column %r twice" % name)
    matches = {}
    for row in right.rows:
        matches.setdefault(row[right_at], []).append([row[i] for i in kept])
    empty = [""] * len(kept)
    rows = []
    for row in left.rows:
        found = matches.get(row[left_at])
        if found:
            rows.extend(row + extra for extra in found)
        elif opts["kind"] == "left":
            rows.append(row + empty)
    return Table(names, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row = table.index(args[1])
    at_col = table.index(args[2])
    at_val = table.index(args[3])
    sums = {}
    heads = {}
    for n, row in enumerate(table.rows, 1):
        head = row[at_col]
        if head == "":
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, n, args[2]))
        if head == args[1]:
            raise TabulaError("%s: row %d: column %r: value %r is the name of the row column"
                              % (table.source, n, args[2], head))
        number = _cell_number(table, n, args[3], row[at_val])
        heads.setdefault(head, None)
        sums.setdefault(row[at_row], {}).setdefault(head, []).append(number)
    # sums of long numbers must stay exact: size the precision to the longest cell
    digits = max([len(c) for row in table.rows for c in row] + [28]) + len(str(len(table.rows))) + 30
    rows = []
    with localcontext() as ctx:
        ctx.prec = digits
        for key, cells in sums.items():
            rows.append([key] + [fmt_decimal(sum(cells[h], Decimal(0))) if h in cells else "0" for h in heads])
    return Table([args[1]] + list(heads), rows, table.source)


def cmd_dedupe(args, opts):
    _need_at_least(args, 2, "dedupe FILE KEY...")
    table = load(args[0])
    at = [table.index(name) for name in args[1:]]
    chosen = {}
    for n, row in enumerate(table.rows):
        key = tuple(row[i] for i in at)
        if opts["keep"] == "last" or key not in chosen:
            chosen[key] = n
    keep = set(chosen.values())
    return table.with_rows([row for n, row in enumerate(table.rows) if n in keep])


def cmd_stats(args, opts):
    _need_at_least(args, 2, "stats FILE COLUMN...")
    table = load(args[0])
    at = [table.index(name) for name in args[1:]]
    found = [[] for _ in at]
    for n, row in enumerate(table.rows, 1):
        for numbers, name, i in zip(found, args[1:], at):
            if row[i].strip():
                numbers.append(_cell_number(table, n, name, row[i]))
    # sums of long numbers must stay exact: size the precision to the longest cell
    digits = max([len(c) for row in table.rows for c in row] + [28]) + len(str(len(table.rows))) + 30
    rows = []
    with localcontext() as ctx:
        ctx.prec = digits
        for name, numbers in zip(args[1:], found):
            if not numbers:
                rows.append([name, "0", "", "", "", ""])
                continue
            ordered = sorted(numbers)
            mid = len(ordered) // 2
            median = ordered[mid] if len(ordered) % 2 else (ordered[mid - 1] + ordered[mid]) / 2
            rows.append([name, str(len(numbers)), fmt_decimal(ordered[0]), fmt_decimal(ordered[-1]),
                         fmt_2dp(sum(numbers, Decimal(0)) / len(numbers)), fmt_2dp(median)])
    return Table(["column", "count", "min", "max", "mean", "median"], rows, table.source)


